from pathlib import Path
import json, hashlib, subprocess, statistics

root=Path('/opt/ioc-extractor')
baseline=root/'.dev/o7-cleanup-original'
profiles={}
checks=[]
for profile in ('first','warm','large'):
    refs={label:json.loads((directory/f'.dev/o7-cleanup-{profile}-{label}/report.json').read_text())
          for label,directory in [('before',baseline),('after',root)]}
    before,after=refs['before'],refs['after']
    for key in ('inputs','runtime_jars','logging_controls','jvm_flags','shape','collapse_hosts','warmups','measurement_mode'):
        assert before[key]==after[key],(profile,key)
    assert before['selected_only'] and after['selected_only']
    assert before['within_provisional_envelope'] is None and after['within_provisional_envelope'] is None
    comparisons={}
    for kind in ('document','import'):
        comparisons[kind]={}
        for i in range(5):
            bm=next(m for m in before['metrics'] if m['kind']==kind and m['iteration']==i)
            am=next(m for m in after['metrics'] if m['kind']==kind and m['iteration']==i)
            for key in ('config_sha256','signature_sha256','outcome','observations'):
                assert bm[key]==am[key],(profile,kind,i,key)
            if kind=='document':
                n=int(am['observations']);u=after['inputs'][kind]['unique'];kept=min(n,10000)
                code=f'EXTRACTION.INDICATOR_SKIPPED:DEBUG={kept}'
                if n>kept: code+=', PIPELINE.DIAGNOSTICS_SUPPRESSED:DEBUG=1'
                expected=f'extracted={n} retained={u} status=COMPLETED diagnostics={n} suppressed={n-kept} severities={{DEBUG={n}}} retained_codes={{{code}}}'
                assert am['outcome']==expected,(profile,am['outcome'],expected)
            for directory,label in [(baseline,'before'),(root,'after')]:
                signature=json.loads((directory/f'.dev/o7-cleanup-{profile}-{label}/{kind}-selected-{i}/signature.json').read_text())
                if kind=='import':
                    assert signature['stage_warnings']==signature['receipt_warnings']==[]
                    assert signature['receipt_outcome']==[['COMMITTED']]
                    assert signature['terminal_state']==[['TERMINAL','SUCCEEDED']]
                else:
                    assert signature['final_fields']['masks'] and signature['final_fields']['ioc_aggregate']
            checks.append({'profile':profile,'workload':kind,'index':i,'equal_inputs_config_outcome_signature':True})
        for metric in ('elapsed_ms','throughput_per_s','allocated_main_bytes','sampled_peak_heap_bytes',
                       'sampled_peak_current_rss_kib','sampled_peak_rss_kib','startup_ms','gc_count','gc_time_ms'):
            b=before['medians'][kind][metric]['selected_median'];a=after['medians'][kind][metric]['selected_median']
            comparisons[kind][metric]={'before_median':b,'after_median':a,'after_over_before':a/b if b else None,
                'before_min':before['medians'][kind][metric]['selected_min'],'before_max':before['medians'][kind][metric]['selected_max'],
                'after_min':after['medians'][kind][metric]['selected_min'],'after_max':after['medians'][kind][metric]['selected_max']}
    warmup_digests={}
    for kind in ('document','import'):
        suffix='html' if kind=='document' else 'csv'
        digests=[]
        for number in range(after['warmups']):
            relative=f'.dev/o7-cleanup-{profile}-after/{kind}-selected-0/warmup-{number}/warmup-{number}.{suffix}'
            other=f'.dev/o7-cleanup-{profile}-before/{kind}-selected-0/warmup-{number}/warmup-{number}.{suffix}'
            assert (root/relative).read_bytes()==(baseline/other).read_bytes()
            digests.append(hashlib.sha256((root/relative).read_bytes()).hexdigest())
        warmup_digests[kind]=digests
    profiles[profile]={'warmup_digests':warmup_digests,'reports':refs,'comparison':comparisons, 'reviewed_signatures': {kind: json.loads((root/f'.dev/o7-cleanup-{profile}-after/{kind}-selected-0/signature.json').read_text()) for kind in ('document','import')}}

diagnostics={label:json.loads((directory/f'.dev/o7-cleanup-diagnostic-{label}/report.json').read_text())
             for label,directory in [('before',baseline),('after',root)]}
for key in ('inputs','runtime_jars','logging_controls','jvm_flags','shape','collapse_hosts','warmups'):
    assert diagnostics['before'][key]==diagnostics['after'][key],key
for kind in ('document','import'):
    bm=next(m for m in diagnostics['before']['metrics'] if m['kind']==kind)
    am=next(m for m in diagnostics['after']['metrics'] if m['kind']==kind)
    assert bm['signature_sha256']==am['signature_sha256'] and bm['config_sha256']==am['config_sha256'] and bm['outcome']==am['outcome']
    assert bm['diagnostic_counters']['preparation_calls']>0 and am['diagnostic_counters']['preparation_calls']>0
    for m in (bm,am):
        counters=m['diagnostic_counters'];n=int(m['observations'])
        assert counters['mapped_cells']==(21*n if kind=='document' else 10*n),counters
        if kind=='document':
            assert counters['artifact_candidates']==7*n//2,counters
            assert counters['prepared_rows']==70 and counters['reserved_ids']==30,counters
        else:assert counters['prepared_import_rows']==n,counters
    checks.append({'profile':'diagnostic','workload':kind,'equal_config_outcome_signature':True})

paths=['tools/dev/processing-route-comparison.py',
 'bootstrap/ioc-app/src/test/java/com/iocextractor/bootstrap/ComparisonDiagnostics.java',
 'bootstrap/ioc-app/src/test/java/com/iocextractor/bootstrap/ProcessingRouteComparison.java',
 'bootstrap/ioc-app/src/test/java/com/iocextractor/bootstrap/ProcessingRouteComparisonTest.java',
 'bootstrap/ioc-app/src/test/resources/application-selected-import-production.yml',
 'bootstrap/ioc-app/src/test/resources/application-customer-routes.yml',
 'bootstrap/ioc-app/src/test/resources/application-golden.yml']
manifest={}
for p in paths:
    assert (root/p).read_bytes()==(baseline/p).read_bytes(),p
    manifest[p]=hashlib.sha256((root/p).read_bytes()).hexdigest()
tracked=subprocess.check_output(['git','diff','--name-only','HEAD'],cwd=baseline,text=True).splitlines()
untracked=subprocess.check_output(['git','ls-files','--others','--exclude-standard'],cwd=baseline,text=True).splitlines()
assert all(p in paths or p=='Makefile' for p in tracked+untracked),(tracked,untracked)
evidence={'status':'qualification only; customer resource acceptance deferred','date':'2026-10-03',
 'production_before':'08d30621876f546ba7f19061fd3fcbd9548b7e29',
 'production_after':'c279f88531b8902b3d54c5d88ee96421e1fb4b05',
 'primary_forks':60,'diagnostic_forks':4,
 'raw_workspaces': {profile: {label: str(directory/f'.dev/o7-cleanup-{profile}-{label}') for label,directory in [('before',baseline),('after',root)]} for profile in ('first','warm','large','diagnostic')},
 'jfr_recordings': {f'{label}-{kind}': {'path': str(directory/f'.dev/o7-cleanup-diagnostic-{label}/{kind}-selected-0/diagnostic.jfr'), 'sha256': hashlib.sha256((directory/f'.dev/o7-cleanup-diagnostic-{label}/{kind}-selected-0/diagnostic.jfr').read_bytes()).hexdigest(), 'summary': (root/f'.dev/o7-cleanup-jfr-{label}-{kind}-summary.txt').read_text()} for label,directory in [('before',baseline),('after',root)] for kind in ('document','import')},
 'execution_order':['after-first','before-first','before-warm','after-warm','after-large','before-large','before-diagnostic','after-diagnostic'],
 'crossover':'independent revision blocks; no alternating before/after crossover',
 'harness_and_policy_sha256':manifest,'baseline_overlay':{'tracked':tracked,'untracked':untracked},
 'checks':checks,'profiles':profiles,'diagnostics':diagnostics, 'validation_source': Path(__file__).read_text()}
output=root/'docs/worknote/0.3.0/data-processing-routing/qualification/optimization/o7-host-collapse.json'
output.write_text(json.dumps(evidence,indent=2)+'\n')
for profile,item in profiles.items():
    for kind,m in item['comparison'].items():
        print(profile,kind,{k:(v['before_median'],v['after_median'],v['after_over_before']) for k,v in m.items()})
for label,report in diagnostics.items():
    for m in report['metrics']:print(label,m['kind'],m['diagnostic_counters'])
print('PASS',len(checks),'checks',output)
